'use strict';
const test=require('node:test'),assert=require('node:assert/strict');
const {searchCheapest,lowerBound,validateStations}=require('./radar-search');
const v={id:'a',name:'Voiture',fuel:'Gazole',consumption:6,tankCapacity:50};
const st=[{id:'a',lat:43,lon:5,price:1.65},{id:'b',lat:43.1,lon:5.1,price:1.7},{id:'c',lat:43.2,lon:5.2,price:2.1}];
const origin={lat:43,lon:5};
const routeBatch=async({stations})=>stations.map(s=>({id:s.id,distanceRoundTripKm:s.id==='a'?36:4}));
const run=(args={})=>searchCheapest({vehicle:v,fillPercent:80,stations:st,origin,routeBatch,batchSize:1,...args});
test('borne minimale = achat seul',()=>assert.equal(lowerBound(v,80,st[0]),66));
test('station plus chère au litre peut gagner',async()=>{const r=await run();assert.equal(r.best.id,'b');assert.equal(r.status,'verified')});
test('élagage sûr après meilleur connu',async()=>{const r=await run();assert.deepEqual(r.skipped,['c']);assert.equal(r.visited,2)});
test('lot de deux',async()=>{const r=await run({batchSize:2});assert.equal(r.best.id,'b');assert.equal(r.requests,1)});
test('aucune station',async()=>{const r=await run({stations:[]});assert.equal(r.status,'unverified');assert.equal(r.requests,0)});
test('route indisponible pouvant gagner => non vérifié',async()=>{const r=await run({routeBatch:async({stations})=>stations.map(s=>({id:s.id,distanceRoundTripKm:s.id==='a'?null:4}))});assert.equal(r.status,'unverified');assert.equal(r.unverified[0].id,'a')});
test('route indisponible trop chère ne bloque pas',async()=>{const r=await run({routeBatch:async({stations})=>stations.map(s=>({id:s.id,distanceRoundTripKm:s.id==='b'?null:0}))});assert.equal(r.status,'verified')});
test('échec réseau sans classement inventé',async()=>{const r=await run({routeBatch:async()=>{throw Error('offline')}});assert.equal(r.status,'unverified');assert.equal(r.best,null)});
test('route absente de la réponse => non vérifié',async()=>{const r=await run({routeBatch:async()=>[]});assert.equal(r.unavailable.length,3)});
test('distance négative refusée',async()=>{const r=await run({routeBatch:async({stations})=>stations.map(s=>({id:s.id,distanceRoundTripKm:-1}))});assert.equal(r.status,'unverified')});
test('pourcentage invalide',async()=>await assert.rejects(run({fillPercent:0}),/Pourcentage/));
test('prix négatif',async()=>await assert.rejects(run({stations:[{...st[0],price:-1}]}),/Prix/));
test('coordonnées invalides',async()=>await assert.rejects(run({stations:[{...st[0],lat:200}]}),/Coordonn/));
test('doublons refusés',async()=>await assert.rejects(run({stations:[st[0],st[0]]}),/dupliqu/));
test('borne égalité conservée',async()=>{const x=[{...st[0],price:1.7},{...st[1],price:1.7}];const r=await run({stations:x,routeBatch:async({stations})=>stations.map(s=>({id:s.id,distanceRoundTripKm:0}))});assert.equal(r.visited,2)});
test('annulation préalable',async()=>{const a=new AbortController();a.abort();const r=await run({signal:a.signal});assert.equal(r.status,'cancelled');assert.equal(r.requests,0)});
test('annulation pendant la requête',async()=>{const a=new AbortController();const r=await run({signal:a.signal,routeBatch:async()=>{a.abort();return []}});assert.equal(r.status,'cancelled')});
test('progression',async()=>{let n=0;await run({onProgress:()=>n++});assert.equal(n,2)});
test('entrées non mutées',async()=>{const before=JSON.stringify(st);await run();assert.equal(JSON.stringify(st),before)});
test('réponse identifiant étranger ignorée',async()=>{const r=await run({routeBatch:async()=>[{id:'inconnu',distanceRoundTripKm:0}]});assert.equal(r.status,'unverified')});
test('lot invalide',async()=>await assert.rejects(run({batchSize:26}),/Lot/));
test('aucune approximation de distance directe',async()=>{const r=await run({routeBatch:async()=>[]});assert.equal(r.completed.length,0)});
